INSERT INTO "KegiatanHarian" ("id", "created_at", "updated_at", "created_by", "updated_by", "source_metadata", "autonumber_id", "idKegiatan", "namaPelapor", "nip", "tanggal", "waktuMulai", "waktuSelesai", "kataKunciKegiatan", "deskripsiKegiatan", "rhkKategori", "fotoKegiatan", "tandaTangan", "unitKerja") VALUES ('7219d6c2-ef6a-4630-b870-b09fab2bc749', '2026-08-06T01:12:55.321Z', '2026-08-06T01:12:55.321Z', NULL, NULL, '{"type":"public_api"}'::jsonb, 183, 183, 'A. Zainudin Sholeh, S.A.P.', '198810082026221001', '2026-08-05', '16:00', '19:00', '', 'Mendampingi peserta didik (pasien) yang menjalani perawatan inap di fasilitas kesehatan, termasuk memantau kebutuhan dasar dan berkoordinasi dengan tenaga medis terkait. Memberikan pendampingan saat waktu makan untuk memastikan asupan nutrisi sesuai anjuran dan kenyamanan peserta didik terpenuhi.', 'RHK 3', '[{"url":"https://uploads.zite.com/orgid-722247/zite-uploads/j9anpelbvb/9Q28dOO3XEQmsS8jCWZVU0Bvc29GTf11_WhatsApp_Image_2026-08-05_at_18.25.22.jpg","filename":"9Q28dOO3XEQmsS8jCWZVU0Bvc29GTf11_WhatsApp_Image_2026-08-05_at_18.25.22.jpg"},{"url":"https://uploads.zite.com/orgid-722247/zite-uploads/j9anpelbvb/rQD7M272QfrBeRBorKfV7MzDU3kTG9t3_WhatsApp_Image_2026-08-05_at_18.29.54.jpg","filename":"rQD7M272QfrBeRBorKfV7MzDU3kTG9t3_WhatsApp_Image_2026-08-05_at_18.29.54.jpg"}]'::jsonb, '[{"url":"https://files.zite.com/orgid-722247/base-3430f61a52e9c704/fieldid-ffKN8uwAquX/oLDVSv9a2XQwzhRU1FHyrq/pasted-image-1785765839992-22iezw3b.png","filename":"pasted-image-1785765839992-22iezw3b.png"}]'::jsonb, 'SEKOLAH RAKYAT TERINTEGRASI 1 KAB. KEDIRI');
