INSERT INTO "KegiatanHarian" ("id", "created_at", "updated_at", "created_by", "updated_by", "source_metadata", "autonumber_id", "idKegiatan", "namaPelapor", "nip", "tanggal", "waktuMulai", "waktuSelesai", "kataKunciKegiatan", "deskripsiKegiatan", "rhkKategori", "fotoKegiatan", "tandaTangan", "unitKerja") VALUES ('1c70781c-4f69-4f1e-850a-65ce7cb1a43f', '2026-08-08T10:33:05.188Z', '2026-08-08T10:33:05.188Z', NULL, NULL, '{"type":"public_api"}'::jsonb, 187, 187, 'A. Zainudin Sholeh, S.A.P.', '198810082026221001', '2026-08-06', '06:30', '07:10', '', 'Melaksanakan pendampingan makan pagi kepada pasien/peserta didik untuk memastikan ketertiban, kecukupan asupan gizi, dan penerapan etika makan yang baik, serta memantau kebutuhan khusus dan menguatkan kemandirian.', 'RHK 3', '[{"url":"https://uploads.zite.com/orgid-722247/zite-uploads/j9anpelbvb/v7Akiig8LdKjCCJGMQWJGjKNxDoxNDTM_WhatsApp_Image_2026-08-07_at_06.38.44.jpg","filename":"v7Akiig8LdKjCCJGMQWJGjKNxDoxNDTM_WhatsApp_Image_2026-08-07_at_06.38.44.jpg"}]'::jsonb, '[{"url":"https://files.zite.com/orgid-722247/base-3430f61a52e9c704/fieldid-ffKN8uwAquX/4gCxrA2jzoRj1h2aXSuYCt/pasted-image-1785765839992-22iezw3b.png","filename":"pasted-image-1785765839992-22iezw3b.png"}]'::jsonb, 'SEKOLAH RAKYAT TERINTEGRASI 1 KAB. KEDIRI');
INSERT INTO "KegiatanHarian" ("id", "created_at", "updated_at", "created_by", "updated_by", "source_metadata", "autonumber_id", "idKegiatan", "namaPelapor", "nip", "tanggal", "waktuMulai", "waktuSelesai", "kataKunciKegiatan", "deskripsiKegiatan", "rhkKategori", "fotoKegiatan", "tandaTangan", "unitKerja") VALUES ('ebabed4b-8a95-4070-9b6a-2af2fa5241dc', '2026-08-08T10:33:05.188Z', '2026-08-08T10:33:05.188Z', NULL, NULL, '{"type":"public_api"}'::jsonb, 188, 188, 'A. Zainudin Sholeh, S.A.P.', '198810082026221001', '2026-08-06', '07:10', '07:30', '', 'Melaksanakan serah terima pergantian shift untuk memastikan kontinuitas pemantauan dan keselamatan pasien, termasuk penyampaian kondisi terkini dan rencana tindak lanjut. Koordinasi dilakukan agar layanan berjalan sesuai prosedur yang berlaku.', 'RHK 4', '[{"url":"https://uploads.zite.com/orgid-722247/zite-uploads/j9anpelbvb/0lFkZg5yXPichUUcrs9evdKFdmfnhBmA_WhatsApp_Image_2026-08-07_at_07.21.42.jpg","filename":"0lFkZg5yXPichUUcrs9evdKFdmfnhBmA_WhatsApp_Image_2026-08-07_at_07.21.42.jpg"}]'::jsonb, '[{"url":"https://files.zite.com/orgid-722247/base-3430f61a52e9c704/fieldid-ffKN8uwAquX/id4h2hs1UQR44nm6RxAQH7/pasted-image-1785765839992-22iezw3b.png","filename":"pasted-image-1785765839992-22iezw3b.png"}]'::jsonb, 'SEKOLAH RAKYAT TERINTEGRASI 1 KAB. KEDIRI');
INSERT INTO "KegiatanHarian" ("id", "created_at", "updated_at", "created_by", "updated_by", "source_metadata", "autonumber_id", "idKegiatan", "namaPelapor", "nip", "tanggal", "waktuMulai", "waktuSelesai", "kataKunciKegiatan", "deskripsiKegiatan", "rhkKategori", "fotoKegiatan", "tandaTangan", "unitKerja") VALUES ('8abcc8da-586d-4b7c-ba2d-b9f3d4d4f7dc', '2026-08-08T11:07:49.606Z', '2026-08-08T11:07:49.606Z', NULL, NULL, '{"type":"public_api"}'::jsonb, 189, 189, 'A. Zainudin Sholeh, S.A.P.', '198810082026221001', '2026-08-07', '15:00', '17:10', '', 'Melaksanakan rapat koordinasi dengan wali asuh, wali asrama, dan guru untuk menyelaraskan program pembinaan serta pemantauan perkembangan peserta didik. Menyusun tindak lanjut dan pembagian peran untuk pelaksanaan kegiatan harian di asrama dan sekolah.', 'RHK 7', '[{"url":"https://uploads.zite.com/orgid-722247/zite-uploads/j9anpelbvb/nvMkYtXntbciH5WJ2Z3EmeDzhmZGUE9S_WhatsApp_Image_2026-08-07_at_20.18.32_1_.jpg","filename":"nvMkYtXntbciH5WJ2Z3EmeDzhmZGUE9S_WhatsApp_Image_2026-08-07_at_20.18.32_1_.jpg"}]'::jsonb, '[{"url":"https://files.zite.com/orgid-722247/base-3430f61a52e9c704/fieldid-ffKN8uwAquX/8HZHdeMHKByhvoBMmD9W9L/pasted-image-1785765839992-22iezw3b.png","filename":"pasted-image-1785765839992-22iezw3b.png"}]'::jsonb, 'SEKOLAH RAKYAT TERINTEGRASI 1 KAB. KEDIRI');
