INSERT INTO "KegiatanHarian" ("id", "created_at", "updated_at", "created_by", "updated_by", "source_metadata", "autonumber_id", "idKegiatan", "namaPelapor", "nip", "tanggal", "waktuMulai", "waktuSelesai", "kataKunciKegiatan", "deskripsiKegiatan", "rhkKategori", "fotoKegiatan", "tandaTangan", "unitKerja") VALUES ('04f0f5e5-f06b-49b6-b479-c4ed8bb2780d', '2026-08-09T02:48:19.829Z', '2026-08-09T02:48:19.829Z', NULL, NULL, '{"type":"public_api"}'::jsonb, 195, 195, 'A. Zainudin Sholeh, S.A.P.', '198810082026221001', '2026-08-08', '15:00', '16:10', '', 'Melaksanakan serah terima pergantian shift untuk memastikan kontinuitas pemantauan dan keselamatan pasien, termasuk penyampaian kondisi terkini dan rencana tindak lanjut. Koordinasi dilakukan agar layanan berjalan sesuai prosedur yang berlaku.', 'RHK 4', '[{"url":"https://uploads.zite.com/orgid-722247/zite-uploads/j9anpelbvb/8YA2Kyo6zZZYxcCEhbmbmSRaETyvfHlS_WhatsApp_Image_2026-08-08_at_15.29.57.jpg","filename":"8YA2Kyo6zZZYxcCEhbmbmSRaETyvfHlS_WhatsApp_Image_2026-08-08_at_15.29.57.jpg"}]'::jsonb, '[{"url":"https://files.zite.com/orgid-722247/base-3430f61a52e9c704/fieldid-ffKN8uwAquX/iy4NxhR9P6oXJ8cCXUvC5Y/pasted-image-1785765839992-22iezw3b.png","filename":"pasted-image-1785765839992-22iezw3b.png"}]'::jsonb, 'SEKOLAH RAKYAT TERINTEGRASI 1 KAB. KEDIRI');
INSERT INTO "KegiatanHarian" ("id", "created_at", "updated_at", "created_by", "updated_by", "source_metadata", "autonumber_id", "idKegiatan", "namaPelapor", "nip", "tanggal", "waktuMulai", "waktuSelesai", "kataKunciKegiatan", "deskripsiKegiatan", "rhkKategori", "fotoKegiatan", "tandaTangan", "unitKerja") VALUES ('3ca2c1b6-639b-4427-9aa4-532ab6629085', '2026-08-09T02:48:19.829Z', '2026-08-09T02:48:19.829Z', NULL, NULL, '{"type":"public_api"}'::jsonb, 196, 196, 'A. Zainudin Sholeh, S.A.P.', '198810082026221001', '2026-08-08', '16:10', '16:35', '', 'Melaksanakan pendampingan makan sore kepada pasien/peserta didik untuk memastikan ketertiban, kecukupan asupan gizi, dan penerapan etika makan yang baik, serta memantau kebutuhan khusus dan menguatkan kemandirian.', 'RHK 2', '[{"url":"https://uploads.zite.com/orgid-722247/zite-uploads/j9anpelbvb/eLr8S1R8y4l7bW7bvQfxG1tEmipbrz3E_WhatsApp_Image_2026-08-08_at_16.13.27.jpg","filename":"eLr8S1R8y4l7bW7bvQfxG1tEmipbrz3E_WhatsApp_Image_2026-08-08_at_16.13.27.jpg"}]'::jsonb, '[{"url":"https://files.zite.com/orgid-722247/base-3430f61a52e9c704/fieldid-ffKN8uwAquX/4sEd8pSPK6spuhzyQTMW1F/pasted-image-1785765839992-22iezw3b.png","filename":"pasted-image-1785765839992-22iezw3b.png"}]'::jsonb, 'SEKOLAH RAKYAT TERINTEGRASI 1 KAB. KEDIRI');
INSERT INTO "KegiatanHarian" ("id", "created_at", "updated_at", "created_by", "updated_by", "source_metadata", "autonumber_id", "idKegiatan", "namaPelapor", "nip", "tanggal", "waktuMulai", "waktuSelesai", "kataKunciKegiatan", "deskripsiKegiatan", "rhkKategori", "fotoKegiatan", "tandaTangan", "unitKerja") VALUES ('13a2f312-8515-4a05-aee9-520c1019d86a', '2026-08-09T02:48:19.829Z', '2026-08-09T02:48:19.829Z', NULL, NULL, '{"type":"public_api"}'::jsonb, 197, 197, 'A. Zainudin Sholeh, S.A.P.', '198810082026221001', '2026-08-08', '18:00', '18:30', '', 'Mendampingi perawat rumah sakit dalam proses pelepasan infus peserta didik yang telah dinyatakan boleh pulang oleh dokter. Memastikan kondisi pascaprosedur stabil dan koordinasi pemulangan berjalan tertib.', 'RHK 4', '[{"url":"https://uploads.zite.com/orgid-722247/zite-uploads/j9anpelbvb/XsqiEIyE3srCgtxt79FhK474mUsIfhOu_WhatsApp_Image_2026-08-09_at_09.31.56.jpg","filename":"XsqiEIyE3srCgtxt79FhK474mUsIfhOu_WhatsApp_Image_2026-08-09_at_09.31.56.jpg"}]'::jsonb, '[{"url":"https://files.zite.com/orgid-722247/base-3430f61a52e9c704/fieldid-ffKN8uwAquX/oGk3a5gpri2d9uaUaJJtME/pasted-image-1785765839992-22iezw3b.png","filename":"pasted-image-1785765839992-22iezw3b.png"}]'::jsonb, 'SEKOLAH RAKYAT TERINTEGRASI 1 KAB. KEDIRI');
INSERT INTO "KegiatanHarian" ("id", "created_at", "updated_at", "created_by", "updated_by", "source_metadata", "autonumber_id", "idKegiatan", "namaPelapor", "nip", "tanggal", "waktuMulai", "waktuSelesai", "kataKunciKegiatan", "deskripsiKegiatan", "rhkKategori", "fotoKegiatan", "tandaTangan", "unitKerja") VALUES ('27dce958-a35a-4160-b5ea-78fd93246f6e', '2026-08-09T02:48:19.829Z', '2026-08-09T02:48:19.829Z', NULL, NULL, '{"type":"public_api"}'::jsonb, 198, 198, 'A. Zainudin Sholeh, S.A.P.', '198810082026221001', '2026-08-08', '18:30', '19:30', '', 'Mengurus administrasi kesehatan, pengambilan/penyerahan obat, serta penerbitan surat kontrol bagi pasien/peserta didik, termasuk koordinasi dengan fasilitas kesehatan untuk penjadwalan tindak lanjut.', 'RHK 4', '[{"url":"https://uploads.zite.com/orgid-722247/zite-uploads/j9anpelbvb/2xW8C8dL2oM9Hpyttt3P0MCZIlfM9hBk_WhatsApp_Image_2026-08-08_at_18.40.46.jpg","filename":"2xW8C8dL2oM9Hpyttt3P0MCZIlfM9hBk_WhatsApp_Image_2026-08-08_at_18.40.46.jpg"}]'::jsonb, '[{"url":"https://files.zite.com/orgid-722247/base-3430f61a52e9c704/fieldid-ffKN8uwAquX/vpmkn1WBidTKvEmmZ7ozaD/pasted-image-1785765839992-22iezw3b.png","filename":"pasted-image-1785765839992-22iezw3b.png"}]'::jsonb, 'SEKOLAH RAKYAT TERINTEGRASI 1 KAB. KEDIRI');
INSERT INTO "KegiatanHarian" ("id", "created_at", "updated_at", "created_by", "updated_by", "source_metadata", "autonumber_id", "idKegiatan", "namaPelapor", "nip", "tanggal", "waktuMulai", "waktuSelesai", "kataKunciKegiatan", "deskripsiKegiatan", "rhkKategori", "fotoKegiatan", "tandaTangan", "unitKerja") VALUES ('cd728a11-8a9b-4c05-bac8-001a1d9ac34f', '2026-08-09T02:48:19.829Z', '2026-08-09T02:48:19.829Z', NULL, NULL, '{"type":"public_api"}'::jsonb, 199, 199, 'A. Zainudin Sholeh, S.A.P.', '198810082026221001', '2026-08-08', '19:30', '20:10', '', 'Melaksanakan pendampingan dan pengantaran peserta didik (pasien) kembali ke Asrama Sekolah Rakyat dari RSM Siti Kotijah, memastikan keselamatan perjalanan dan kelancaran proses serah terima. Melakukan koordinasi singkat dengan petugas kesehatan serta pemantauan awal kondisi peserta didik setibanya di asrama.', 'RHK 3', '[{"url":"https://uploads.zite.com/orgid-722247/zite-uploads/j9anpelbvb/wmZIZT1aJIrBylX4P03Hut0UYOC2KNiD_WhatsApp_Image_2026-08-09_at_09.41.46.jpg","filename":"wmZIZT1aJIrBylX4P03Hut0UYOC2KNiD_WhatsApp_Image_2026-08-09_at_09.41.46.jpg"}]'::jsonb, '[{"url":"https://files.zite.com/orgid-722247/base-3430f61a52e9c704/fieldid-ffKN8uwAquX/txL3VVwCa6dQufAramyLWU/pasted-image-1785765839992-22iezw3b.png","filename":"pasted-image-1785765839992-22iezw3b.png"}]'::jsonb, 'SEKOLAH RAKYAT TERINTEGRASI 1 KAB. KEDIRI');
